"""Write A9_decide.lean: for every subset D of the divisors of M (M = 12, 18, 8, 1, 5), the answers of the
independent Python program for "is D an up-set" and "corners of D", stated for the kernel to check by `decide`."""
import itertools
from check_table_defs import divisors, is_upset_intended, corners_intended

def fs(xs):
    xs = sorted(xs)
    return '(∅ : Finset ℕ)' if not xs else '({' + ', '.join(map(str, xs)) + '} : Finset ℕ)'

out = ['import Pnq.Upset', 'open Pnq.Upset', '',
       '/-! Generated by gen_decide.py. The up-set claims are stated in the bounded form (see A5_facts.lean,',
       '`Audit.isUpSet_iff_B`, for the equivalence with `IsUpSet` when M ≠ 0) and then transferred. -/', '',
       'theorem upB {M : ℕ} (hM : M ≠ 0) {D : Finset ℕ}',
       '    (h : (∀ d ∈ D, d ∣ M ∧ d ≠ 1) ∧ ∀ d ∈ D, ∀ e ∈ M.divisors, d ∣ e → e ∈ D) : IsUpSet M D :=',
       '  ⟨h.1, fun d hd e hde heM => h.2 d hd e (Nat.mem_divisors.2 ⟨heM, hM⟩) hde⟩', '',
       'theorem notUpB {M : ℕ} {D : Finset ℕ}',
       '    (h : ¬ ((∀ d ∈ D, d ∣ M ∧ d ≠ 1) ∧ ∀ d ∈ D, ∀ e ∈ M.divisors, d ∣ e → e ∈ D)) : ¬ IsUpSet M D :=',
       '  fun hD => h ⟨hD.1, fun d hd e he hde => hD.2 d hd e hde (Nat.dvd_of_mem_divisors he)⟩', '']
cnt = [0, 0, 0]
for M in (1, 5, 8, 12, 18):
    dv = divisors(M)
    for k in range(len(dv) + 1):
        for D in itertools.combinations(dv, k):
            Dset = set(D)
            if is_upset_intended(M, Dset):
                out.append(f'example : IsUpSet {M} {fs(D)} := upB (by decide) (by decide)'); cnt[0] += 1
            else:
                out.append(f'example : ¬ IsUpSet {M} {fs(D)} := notUpB (by decide)'); cnt[1] += 1
            C = corners_intended(M, Dset)
            out.append(f'example : corners {M} {fs(D)} = {fs(C)} := by decide'); cnt[2] += 1
# sets with a non-divisor, with 0, with 1
for (M, D) in [(12, [5]), (12, [0]), (12, [1, 2, 3, 4, 6, 12]), (12, [12, 24]), (12, [8, 12]), (18, [4, 18])]:
    assert not is_upset_intended(M, set(D))
    out.append(f'example : ¬ IsUpSet {M} {fs(D)} := notUpB (by decide)'); cnt[1] += 1
    out.append(f'example : corners {M} {fs(D)} = {fs(corners_intended(M, set(D)))} := by decide'); cnt[2] += 1
open('A9_decide.lean', 'w', encoding='utf-8').write('\n'.join(out) + '\n')
print('up-set examples %d, not-up-set examples %d, corners examples %d' % tuple(cnt))
